#
#    DebuggerPythonInterface.py
#
#    Thin layer between browser (websocket) and debugged python script generated by GraphLang, python version of
#    DebuggerCppBrowserInterface.py. Instead of gdb there is python standard library debugger bdb running inside debugged
#    script process.
#
#    How it works:
#
#       browser  <--websocket (port 8889)-->  DebuggerPythonInterface.py (this script, server)  <--TCP JSON lines-->  debugged script (debugee)
#
#       1. PHP starts this script (?q=runPythonDebugServer), it opens websocket and waits for browser commands.
#       2. Browser sends "file <path to main.py>", "b <line>" for each breakpoint and "start".
#       3. On "start" this script opens local TCP port and runs debugged script as subprocess with environment variable
#          GRAPHLANG_PYTHON_DEBUG_PORT=<port> and PYTHONPATH containing this directory.
#       4. Generated script template (see TranslateToPythonCode_2_TranslatorObject.js, getPythonCodeUsingTemplate_desktop())
#          checks this environment variable and instead of calling main() calls DebuggerPythonInterface.runDebugee(main, __file__),
#          this imports THIS FILE as module in debugee process and runs main() under bdb debugger connected back to this server.
#       5. Each time debugee stops (start, breakpoint, step) it sends "stopped" event and waits for commands (eval variable,
#          continue, step, ...).
#
#    Browser messages (similar to gdb commands so browser side stays similar to C++ debugger):
#       test echo <text>                    reply plain <text> (used to check layer is running)
#       end debugging                       kill debugee and exit this script
#       get random number                   reply random number (test)
#       file <path>                         set script which will be debugged
#       b <line> | break <line>             set breakpoint, line is moved to next executable line (like gdb does)
#       delete [number] | clear <line>      delete breakpoint(s)
#       info breakpoint | -break-list       list breakpoints
#       start | run                         run script and stop at first line of main()
#       c | continue | -exec-continue       continue to next breakpoint
#       n | next | -exec-next               step over
#       s | step | -exec-step               step into
#       finish | -exec-finish               run until current function returns
#       p <expr> | print <expr> | -data-evaluate-expression <expr>     evaluate expression in current frame
#       info locals | locals                local variables of current frame
#       frame | where | bt                  current location / stack
#       status | -gdb-show confirm          wait shortly for program stop when it is running (polling)
#       kill                                kill debugged program
#
#    Every reply (except test echo / random) is JSON list of records in same shape as pygdbmi output
#       [{"type": "result"|"notify"|"output"|"console", "message": str|None, "payload": ..., "token": None, "stream": "stdout"}]
#    stopped notify payload: {"reason": "start"|"breakpoint-hit"|"end-stepping-range"|"function-finished"|"exited-normally"|"exited"|"exited-signalled",
#                             "bkptno": str, "frame": {"file", "fullname", "line", "func"}, "exit-code": str}
#
#    To run this this needs to be installed:
#       - pip3 install websockets
#
import os
import sys
import json
import random
import socket
import bdb
import types
import traceback
import logging
import argparse
import asyncio

ENV_DEBUG_PORT = "GRAPHLANG_PYTHON_DEBUG_PORT"
ENABLE_STDOUT = False
ENABLE_LOGGING = False
logger = logging.getLogger("DebuggerPythonInterface")

MAX_VALUE_LENGTH = 1000                 # max length of evaluated value text sent to browser
CONTINUE_WAIT_TIMEOUT_SECONDS = 30      # how long continue/step waits for program to stop, after that status "running" is returned
DEBUGEE_CONNECT_TIMEOUT_SECONDS = 15    # how long wait for debugee to connect back after start


def _log(msg):
    if ENABLE_STDOUT:
        print(msg, flush=True)
    if ENABLE_LOGGING:
        logger.info(msg)


def _record(type, message=None, payload=None):
    """Create one response record in pygdbmi format."""
    return {"type": type, "message": message, "payload": payload, "token": None, "stream": "stdout"}


def _valueToText(value):
    """Value displayed to user, strings without quotes (like C++ debugger shows string value), others as repr()."""
    try:
        text = value if isinstance(value, str) else repr(value)
    except Exception as e:
        text = f"<repr error: {e}>"
    if len(text) > MAX_VALUE_LENGTH:
        text = text[:MAX_VALUE_LENGTH] + "..."
    return text


def getExecutableLines(path):
    """Return sorted list of line numbers in python file where code is executed (where breakpoint can be hit)."""
    with open(path, "r", encoding="utf-8") as f:
        source = f.read()
    codeObj = compile(source, path, "exec")
    lines = set()
    stack = [codeObj]
    while stack:
        co = stack.pop()
        for _start, _end, lineNo in co.co_lines():
            if lineNo is not None:
                lines.add(lineNo)
        stack.extend(c for c in co.co_consts if isinstance(c, types.CodeType))
    return sorted(lines)


#######################################################################################################################
#   DEBUGEE SIDE - this runs inside debugged script process, imported by generated script template
#######################################################################################################################

class _GraphLangBdb(bdb.Bdb):
    """bdb debugger controlled by commands from DebuggerPythonInterface server over TCP socket (JSON lines)."""

    def __init__(self, sock, targetFile):
        super().__init__(skip=["DebuggerPythonInterface", "bdb", "importlib*"])
        self.sock = sock
        self.sockFile = sock.makefile("r", encoding="utf-8")
        self.targetFile = self.canonic(targetFile)
        self.resumeMode = "start"   # start | continue | next | step | finish, used to say why program stopped

    def send(self, obj):
        self.sock.sendall((json.dumps(obj) + "\n").encode("utf-8"))

    def readCommand(self):
        line = self.sockFile.readline()
        if not line:
            return {"cmd": "quit"}
        return json.loads(line)

    def setBreakpoints(self, lines):
        self.clear_all_file_breaks(self.targetFile)
        result = []
        for lineNo in lines:
            errorMsg = self.set_break(self.targetFile, int(lineNo))
            result.append({"line": int(lineNo), "error": errorMsg})
        return result

    def serveBeforeRun(self):
        """Handle commands before main() is started (setting breakpoints), returns when 'run' received."""
        self.send({"type": "event", "event": "connected", "pid": os.getpid(), "file": self.targetFile})
        while True:
            cmd = self.readCommand()
            if cmd["cmd"] == "setBreakpoints":
                self.send({"type": "reply", "result": self.setBreakpoints(cmd.get("lines", []))})
            elif cmd["cmd"] == "run":
                return True
            elif cmd["cmd"] == "quit":
                return False
            else:
                self.send({"type": "reply", "error": f"program not started, command {cmd['cmd']} not allowed"})

    def frameInfo(self, frame):
        return {
            "file": os.path.basename(frame.f_code.co_filename),
            "fullname": frame.f_code.co_filename,
            "line": str(frame.f_lineno),
            "func": frame.f_code.co_name,
        }

    def user_call(self, frame, argument_list):
        pass

    def user_return(self, frame, return_value):
        # stop after function finished only when finish was requested from this frame, otherwise ignore
        if self.resumeMode == "finish" and self.canonic(frame.f_code.co_filename) == self.targetFile and frame is getattr(self, "_finishFrame", None):
            self.interaction(frame, "function-finished", returnValue=return_value)

    def user_exception(self, frame, exc_info):
        pass

    def user_line(self, frame):
        # stop only in generated script, stepping through other modules continues
        if self.canonic(frame.f_code.co_filename) != self.targetFile:
            return
        reason = {"start": "start", "continue": "breakpoint-hit", "finish": "breakpoint-hit"}.get(self.resumeMode, "end-stepping-range")
        self.interaction(frame, reason)

    def interaction(self, frame, reason, returnValue=None):
        hasBreakpoint = len(self.get_breaks(self.targetFile, frame.f_lineno)) > 0
        event = {"type": "event", "event": "stopped", "reason": reason, "hasBreakpoint": hasBreakpoint, "frame": self.frameInfo(frame)}
        if reason == "function-finished":
            event["returnValue"] = _valueToText(returnValue)
        self.send(event)

        while True:
            cmd = self.readCommand()
            name = cmd["cmd"]
            if name == "eval":
                try:
                    value = eval(cmd["expr"], frame.f_globals, frame.f_locals)
                    self.send({"type": "reply", "value": _valueToText(value), "valueType": type(value).__name__})
                except Exception as e:
                    self.send({"type": "reply", "error": f"{type(e).__name__}: {e}"})
            elif name == "locals":
                self.send({"type": "reply", "locals": {k: _valueToText(v) for k, v in frame.f_locals.items() if not k.startswith("__")}})
            elif name == "stack":
                stack, _index = self.get_stack(frame, None)
                frames = [self.frameInfo(f) for f, _ln in stack if self.canonic(f.f_code.co_filename) == self.targetFile]
                self.send({"type": "reply", "stack": frames})
            elif name == "setBreakpoints":
                self.send({"type": "reply", "result": self.setBreakpoints(cmd.get("lines", []))})
            elif name == "continue":
                self.resumeMode = "continue"
                self.set_continue()
                return
            elif name == "next":
                self.resumeMode = "next"
                self.set_next(frame)
                return
            elif name == "step":
                self.resumeMode = "step"
                self.set_step()
                return
            elif name == "finish":
                self.resumeMode = "finish"
                self._finishFrame = frame
                self.set_return(frame)
                return
            elif name == "quit":
                self.set_quit()
                return
            else:
                self.send({"type": "reply", "error": f"unknown debugee command: {name}"})


def runDebugee(mainFunc, scriptFile=None):
    """
    Entry point called from generated python script when started by DebuggerPythonInterface.py (environment variable
    GRAPHLANG_PYTHON_DEBUG_PORT is set). Connects to debugger layer and runs mainFunc under bdb debugger.
    """
    port = int(os.environ[ENV_DEBUG_PORT])
    targetFile = os.path.abspath(scriptFile if scriptFile else mainFunc.__code__.co_filename)
    sock = socket.create_connection(("127.0.0.1", port))
    debugger = _GraphLangBdb(sock, targetFile)

    exitEvent = {"type": "event", "event": "exited", "reason": "exited-normally", "exitCode": 0, "exception": None}
    try:
        if debugger.serveBeforeRun():
            debugger.runcall(mainFunc)
        else:
            exitEvent.update({"reason": "exited-signalled", "exitCode": 1})
    except bdb.BdbQuit:
        exitEvent.update({"reason": "exited-signalled", "exitCode": 1})
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else (0 if e.code is None else 1)
        exitEvent.update({"reason": "exited-normally" if code == 0 else "exited", "exitCode": code})
    except BaseException:
        exitEvent.update({"reason": "exited", "exitCode": 1, "exception": traceback.format_exc()})
        traceback.print_exc()
    finally:
        sys.settrace(None)
        sys.stdout.flush()
        sys.stderr.flush()

    try:
        debugger.send(exitEvent)
        sock.close()
    except OSError:
        pass
    os._exit(exitEvent["exitCode"])


#######################################################################################################################
#   SERVER SIDE - websocket server for browser, controls debugee process
#######################################################################################################################

class DebuggerPythonBrowserInterface:
    websocketHost = "0.0.0.0"
    websocketPort = 8889

    def __init__(self):
        self.scriptPath = None
        self.breakpoints = []           # [{"number": int, "requestedLine": int, "line": int}]
        self.breakpointCounter = 0
        self.process = None
        self.debugeeReader = None
        self.debugeeWriter = None
        self.debugeeConnected = None    # asyncio.Event
        self.tcpServer = None
        self.replyQueue = None
        self.eventQueue = None
        self.programOutput = []         # program stdout/stderr chunks not yet sent to browser
        self.state = "notStarted"       # notStarted | starting | stopped | running | exited
        self.exitReported = False
        self.lastStopped = None
        self.backgroundTasks = set()

    #------------------------------------------------------------------------------------------------------------------
    #   helpers
    #------------------------------------------------------------------------------------------------------------------
    def _spawn(self, coroutine):
        task = asyncio.ensure_future(coroutine)
        self.backgroundTasks.add(task)
        task.add_done_callback(self.backgroundTasks.discard)
        return task

    def _breakpointByLine(self, line):
        for bp in self.breakpoints:
            if bp["line"] == line:
                return bp
        return None

    def _breakpointTable(self):
        body = []
        for bp in self.breakpoints:
            body.append({
                "number": str(bp["number"]),
                "type": "breakpoint",
                "enabled": "y",
                "file": os.path.basename(self.scriptPath) if self.scriptPath else "",
                "fullname": self.scriptPath,
                "line": str(bp["line"]),
                "original-location": f"{self.scriptPath}:{bp['requestedLine']}",
            })
        return {"BreakpointTable": {"nr_rows": str(len(body)), "body": body}}

    def _drainOutput(self):
        if not self.programOutput:
            return []
        text = "".join(self.programOutput)
        self.programOutput = []
        return [_record("output", None, text)]

    async def _sendToDebugee(self, obj):
        self.debugeeWriter.write((json.dumps(obj) + "\n").encode("utf-8"))
        await self.debugeeWriter.drain()

    async def _debugeeRequest(self, obj, timeout=10):
        """Send command to stopped debugee and wait for its reply."""
        if self.state != "stopped":
            return {"error": f"program is not stopped (state: {self.state})"}
        await self._sendToDebugee(obj)
        try:
            return await asyncio.wait_for(self.replyQueue.get(), timeout)
        except asyncio.TimeoutError:
            return {"error": "debugee did not reply in time"}

    def _eventToRecords(self, event):
        """Convert debugee event into records for browser, updates state."""
        if event["event"] == "stopped":
            self.state = "stopped"
            line = int(event["frame"]["line"])
            payload = {"reason": event["reason"], "frame": event["frame"], "thread-id": "1"}
            bp = self._breakpointByLine(line)
            if bp is not None and event.get("hasBreakpoint") and event["reason"] != "start":
                payload["bkptno"] = str(bp["number"])
                payload["reason"] = "breakpoint-hit"
            if "returnValue" in event:
                payload["return-value"] = event["returnValue"]
            self.lastStopped = payload
            return [_record("notify", "stopped", payload)]
        elif event["event"] == "exited":
            self.state = "exited"
            payload = {"reason": event.get("reason", "exited"), "exit-code": str(event.get("exitCode", 0))}
            records = [_record("notify", "stopped", payload)]
            if event.get("exception"):
                records.append(_record("console", None, event["exception"]))
            return records
        return [_record("notify", event["event"], event)]

    async def _waitForEvent(self, timeout):
        """Wait for stopped/exited event from debugee, returns records, empty list on timeout."""
        try:
            event = await asyncio.wait_for(self.eventQueue.get(), timeout)
        except asyncio.TimeoutError:
            return []
        await asyncio.sleep(0.05)   # let output reader catch program output written before stop
        return self._eventToRecords(event)

    #------------------------------------------------------------------------------------------------------------------
    #   debugee process handling
    #------------------------------------------------------------------------------------------------------------------
    async def _onDebugeeConnected(self, reader, writer):
        if self.debugeeWriter is not None:
            writer.close()  # only one debugee at a time
            return
        self.debugeeReader = reader
        self.debugeeWriter = writer
        self._spawn(self._readDebugee(reader))

    async def _readDebugee(self, reader):
        while True:
            line = await reader.readline()
            if not line:
                break
            try:
                msg = json.loads(line.decode("utf-8"))
            except ValueError:
                continue
            _log(f"debugee> {line[:200]!r}")
            if msg.get("type") == "reply":
                await self.replyQueue.put(msg)
            elif msg.get("event") == "connected":
                self.debugeeConnected.set()
            else:
                if msg.get("event") == "exited":
                    self.exitReported = True
                await self.eventQueue.put(msg)

    async def _readProgramOutput(self, stream):
        while True:
            chunk = await stream.read(4096)
            if not chunk:
                break
            self.programOutput.append(chunk.decode("utf-8", errors="replace"))

    async def _watchProcess(self, process):
        returnCode = await process.wait()
        await asyncio.sleep(0.5)    # debugee normally sends exited event itself, wait for it
        if process is self.process and not self.exitReported:
            self.exitReported = True
            await self.eventQueue.put({"event": "exited", "reason": "exited", "exitCode": returnCode, "exception": None})

    async def killDebugee(self):
        if self.process is not None and self.process.returncode is None:
            try:
                if self.state == "stopped" and self.debugeeWriter is not None:
                    await self._sendToDebugee({"cmd": "quit"})
                    await asyncio.wait_for(self.process.wait(), 2)
            except Exception:
                pass
            if self.process.returncode is None:
                self.process.kill()
                await self.process.wait()
        if self.debugeeWriter is not None:
            try:
                self.debugeeWriter.close()
            except Exception:
                pass
        if self.tcpServer is not None:
            self.tcpServer.close()
        self.process = None
        self.debugeeReader = None
        self.debugeeWriter = None
        self.tcpServer = None
        self.state = "notStarted"

    async def startDebugee(self):
        if not self.scriptPath:
            return [_record("result", "error", {"msg": "No script specified, use: file <path to script>"})]

        await self.killDebugee()
        self.replyQueue = asyncio.Queue()
        self.eventQueue = asyncio.Queue()
        self.debugeeConnected = asyncio.Event()
        self.programOutput = []
        self.exitReported = False
        self.lastStopped = None
        self.state = "starting"

        self.tcpServer = await asyncio.start_server(self._onDebugeeConnected, "127.0.0.1", 0)
        port = self.tcpServer.sockets[0].getsockname()[1]

        env = os.environ.copy()
        env[ENV_DEBUG_PORT] = str(port)
        env["PYTHONUNBUFFERED"] = "1"
        env["PYTHONIOENCODING"] = "utf-8"
        thisDir = os.path.dirname(os.path.abspath(__file__))
        env["PYTHONPATH"] = thisDir + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")

        self.process = await asyncio.create_subprocess_exec(
            sys.executable, "-u", self.scriptPath,
            cwd=os.path.dirname(self.scriptPath),
            env=env,
            stdin=asyncio.subprocess.DEVNULL,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.STDOUT,
        )
        self._spawn(self._readProgramOutput(self.process.stdout))
        self._spawn(self._watchProcess(self.process))
        _log(f"debugee started pid {self.process.pid}, port {port}")

        # wait till script connects back, if it ends earlier its template is not prepared for remote debugging
        connectedTask = asyncio.ensure_future(self.debugeeConnected.wait())
        exitTask = asyncio.ensure_future(self.process.wait())
        done, _pending = await asyncio.wait({connectedTask, exitTask}, timeout=DEBUGEE_CONNECT_TIMEOUT_SECONDS, return_when=asyncio.FIRST_COMPLETED)
        exitTask.cancel()
        if connectedTask not in done:
            connectedTask.cancel()
            await asyncio.sleep(0.2)
            records = self._drainOutput()
            await self.killDebugee()
            self.state = "exited"
            records.append(_record("result", "error", {"msg": "Script did not connect to debugger. Is it generated with GraphLang python template prepared for remote debugging (GRAPHLANG_PYTHON_DEBUG_PORT)?"}))
            return records

        self.state = "stopped"  # debugee waits for commands before running main()
        reply = await self._debugeeRequest({"cmd": "setBreakpoints", "lines": [bp["line"] for bp in self.breakpoints]})
        records = [_record("result", "done", {"pid": str(self.process.pid), "breakpoints": reply.get("result", reply)})]

        self.state = "running"
        await self._sendToDebugee({"cmd": "run"})
        records += await self._waitForEvent(CONTINUE_WAIT_TIMEOUT_SECONDS)
        if self.state == "running":
            records.append(_record("result", "running", None))
        return self._drainOutput() + records

    async def resumeDebugee(self, cmdName):
        if self.state == "running":
            return [_record("result", "error", {"msg": "The program is running, wait for it to stop (use status)."})]
        if self.state != "stopped":
            return [_record("result", "error", {"msg": "The program is not being run."})]
        self.state = "running"
        await self._sendToDebugee({"cmd": cmdName})
        records = [_record("result", "running", None)]
        records += await self._waitForEvent(CONTINUE_WAIT_TIMEOUT_SECONDS)
        return self._drainOutput() + records

    #------------------------------------------------------------------------------------------------------------------
    #   browser commands
    #------------------------------------------------------------------------------------------------------------------
    def cmdFile(self, argument):
        path = os.path.abspath(argument.strip().strip('"').replace("\\\\", "\\"))
        if not os.path.isfile(path):
            return [_record("result", "error", {"msg": f"{path}: No such file or directory."})]
        try:
            getExecutableLines(path)
        except SyntaxError as e:
            return [_record("result", "error", {"msg": f"Syntax error in {path}: {e}"})]
        self.scriptPath = path
        # breakpoints from previous file are no longer valid
        self.breakpoints = []
        return [_record("console", None, f"Reading python script {path}...\n"), _record("result", "done", {"file": path})]

    async def cmdBreak(self, argument):
        if not self.scriptPath:
            return [_record("result", "error", {"msg": "No script specified, use: file <path to script>"})]
        argument = argument.strip()
        if ":" in argument:
            argument = argument.rsplit(":", 1)[1]
        try:
            requestedLine = int(argument)
        except ValueError:
            return [_record("result", "error", {"msg": f"Breakpoint line must be number, got: {argument}"})]

        executableLines = getExecutableLines(self.scriptPath)
        actualLine = next((ln for ln in executableLines if ln >= requestedLine), None)
        if actualLine is None:
            return [_record("result", "error", {"msg": f"No code for line {requestedLine} in file \"{self.scriptPath}\"."})]

        self.breakpointCounter += 1
        bp = {"number": self.breakpointCounter, "requestedLine": requestedLine, "line": actualLine}
        self.breakpoints.append(bp)
        if self.state == "stopped":
            await self._debugeeRequest({"cmd": "setBreakpoints", "lines": [b["line"] for b in self.breakpoints]})

        records = []
        if actualLine != requestedLine:
            records.append(_record("console", None, f"Breakpoint {bp['number']} moved from line {requestedLine} to next code line {actualLine}\n"))
        records.append(_record("result", "done", {"bkpt": {
            "number": str(bp["number"]), "type": "breakpoint", "file": os.path.basename(self.scriptPath),
            "fullname": self.scriptPath, "line": str(actualLine), "original-location": f"{self.scriptPath}:{requestedLine}",
        }}))
        return records

    async def cmdDelete(self, argument, byLine=False):
        argument = argument.strip()
        if argument == "":
            self.breakpoints = []
        else:
            try:
                value = int(argument.rsplit(":", 1)[-1])
            except ValueError:
                return [_record("result", "error", {"msg": f"Wrong argument: {argument}"})]
            key = "requestedLine" if byLine else "number"
            self.breakpoints = [bp for bp in self.breakpoints if bp[key] != value and not (byLine and bp["line"] == value)]
        if self.state == "stopped":
            await self._debugeeRequest({"cmd": "setBreakpoints", "lines": [b["line"] for b in self.breakpoints]})
        return [_record("result", "done", self._breakpointTable())]

    async def cmdEval(self, expression):
        reply = await self._debugeeRequest({"cmd": "eval", "expr": expression})
        if "error" in reply:
            return [_record("result", "error", {"msg": reply["error"]})]
        return [_record("result", "done", {"value": reply["value"], "type": reply.get("valueType")})]

    async def cmdLocals(self):
        reply = await self._debugeeRequest({"cmd": "locals"})
        if "error" in reply:
            return [_record("result", "error", {"msg": reply["error"]})]
        text = "".join(f"{k} = {v}\n" for k, v in reply["locals"].items())
        return [_record("console", None, text), _record("result", "done", {"locals": [{"name": k, "value": v} for k, v in reply["locals"].items()]})]

    async def cmdFrame(self):
        if self.state != "stopped" or self.lastStopped is None:
            return [_record("result", "error", {"msg": f"No stack (program state: {self.state})."})]
        reply = await self._debugeeRequest({"cmd": "stack"})
        frame = self.lastStopped.get("frame", {})
        return [
            _record("console", None, f"#0  {frame.get('func')} () at {frame.get('file')}:{frame.get('line')}\n"),
            _record("result", "done", {"frame": frame, "stack": reply.get("stack", [])}),
        ]

    async def cmdStatus(self):
        if self.state == "running":
            records = await self._waitForEvent(1)
            if records:
                return self._drainOutput() + records
        return self._drainOutput() + [_record("result", "done", {"state": self.state, "value": "off"})]

    async def cmdKill(self):
        if self.process is None or self.process.returncode is not None:
            await self.killDebugee()
            return self._drainOutput() + [_record("result", "error", {"msg": "The program is not being run."})]
        await self.killDebugee()
        return self._drainOutput() + [_record("console", None, "[Inferior 1 (process) killed]\n"), _record("result", "done", None)]

    async def handleCommand(self, message):
        """Handle browser command, returns list of records."""
        message = message.strip()
        parts = message.split(None, 1)
        command = parts[0] if parts else ""
        argument = parts[1] if len(parts) > 1 else ""

        if command == "file":
            return self.cmdFile(argument)
        if command in ("b", "break", "-break-insert"):
            return await self.cmdBreak(argument)
        if command in ("delete", "d", "-break-delete"):
            return await self.cmdDelete(argument)
        if command == "clear":
            return await self.cmdDelete(argument, byLine=True)
        if message in ("info breakpoint", "info breakpoints", "info b", "-break-list"):
            return [_record("result", "done", self._breakpointTable())]
        if command in ("start", "run", "r", "-exec-run"):
            return await self.startDebugee()
        if command in ("c", "continue", "-exec-continue"):
            return await self.resumeDebugee("continue")
        if command in ("n", "next", "-exec-next"):
            return await self.resumeDebugee("next")
        if command in ("s", "step", "-exec-step"):
            return await self.resumeDebugee("step")
        if command in ("finish", "-exec-finish"):
            return await self.resumeDebugee("finish")
        if command in ("p", "print", "-data-evaluate-expression"):
            return await self.cmdEval(argument)
        if message in ("info locals", "locals", "-stack-list-locals"):
            return await self.cmdLocals()
        if command in ("frame", "where", "bt", "backtrace", "-stack-info-frame"):
            return await self.cmdFrame()
        if message in ("status", "-gdb-show confirm"):
            return await self.cmdStatus()
        if command == "kill":
            return await self.cmdKill()
        if command == "output":
            return self._drainOutput() + [_record("result", "done", None)]
        return [_record("result", "error", {"msg": f"Undefined command: \"{message}\"."})]

    async def processBrowserMessage(self, websocket):
        try:
            async for message in websocket:
                _log(f"Received: {message[:200]}")
                try:
                    if message == "end debugging":
                        await self.killDebugee()
                        try:
                            await websocket.close()
                        except Exception:
                            pass
                        os._exit(0)
                    elif message.startswith("get random"):
                        await websocket.send(str(random.random()))
                    elif message.startswith("test echo"):
                        await websocket.send(message[len("test echo"):].strip())
                    else:
                        records = await self.handleCommand(message)
                        _log(f"Reply: {json.dumps(records)[:500]}")
                        await websocket.send(json.dumps(records))
                except Exception as e:
                    if ENABLE_LOGGING:
                        logger.error(f"Error processing message: {e}", exc_info=True)
                    try:
                        await websocket.send(json.dumps([_record("result", "error", {"msg": f"debugger layer error: {e}"})]))
                    except Exception:
                        pass
        except Exception as e:
            if ENABLE_LOGGING:
                logger.error(f"Fatal error in websocket handler: {e}", exc_info=True)

    async def handlerAsyncLoop(self):
        import websockets   # imported here so debugee (which imports this file) does not need it

        async with websockets.serve(
            self.processBrowserMessage,
            self.websocketHost,
            self.websocketPort,
            max_size=10 * 1024 * 1024,
            ping_interval=20,
            ping_timeout=20,
            close_timeout=10,
        ):
            _log(f"python debugger websocket server started on port {self.websocketPort}")
            await asyncio.Future()  # run forever

    def startAsyncLoop(self):
        asyncio.run(self.handlerAsyncLoop())


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="GraphLang python debugger websocket layer")
    parser.add_argument("--stdout", action="store_true", help="Enable stdout output")
    parser.add_argument("--logging", action="store_true", help="Enable logging to log file tmp/python_debugger_websocket.log")
    parser.add_argument("--port", type=int, default=DebuggerPythonBrowserInterface.websocketPort, help="websocket port")
    args, unknown = parser.parse_known_args()

    ENABLE_STDOUT = args.stdout
    ENABLE_LOGGING = args.logging
    if ENABLE_LOGGING:
        os.makedirs("tmp", exist_ok=True)
        logging.basicConfig(level=logging.DEBUG, filename="tmp/python_debugger_websocket.log")

    browserInterface = DebuggerPythonBrowserInterface()
    browserInterface.websocketPort = args.port
    browserInterface.startAsyncLoop()
